import json,html
from pathlib import Path
ROOT=Path(__file__).parent.parent/'output';out=ROOT/'household-change-verification'
cases=[json.loads((out/(n+'.json')).read_text()) for n in ['returned','rejected','rejected-level2','history']]
ui={p.name:json.loads(p.read_text()) for p in out.glob('*-ui.json')};cleanup=json.loads((out/'fixture-cleanup.json').read_text());preserved=json.loads((ROOT/'ooru-meeting-audit/verification/preservation.json').read_text())
assert all(s['status']=='passed' for s in [*cases,*ui.values(),preserved]) and cleanup['status']=='completed'
checks=['Level-1 return → officer correction and same-request resubmission → first approval → level-2 return → second correction and resubmission restarting level 1 → both approvals.','Master room count remains 2 through proposals, returns, resubmissions and first approvals. Final approval applies only the corrected value 5; unrelated business fields remain unchanged. Both return events remain in review history.','Separate permanent-rejection cases at levels 1 and 2 cannot apply their old proposals. The master value and version-history count remain unchanged; rejected requests show their reasons and no correction action.','Fresh post-fix history regression: two approvals apply room count 3, the history snapshot retains 3, and the approved change comparison correctly shows old value 2 and new value 3.','Desktop 1440px and mobile 390px checks cover change-request cards/list/detail, correction editor, review controls, old/new values and version-history screens. Checked views have no page overflow, clipped labels, raw underscore keys or JavaScript errors.']
fixes=['Correction editor now sends only the fields owned by the edited section, preserving row identifiers and numeric choice types. Previously it sent the whole household record and the server correctly rejected unrelated fields. Server field restrictions remain enabled.','Correction-popup labels wrap instead of truncating, and the popup uses the registry’s green theme.','Household history schema now includes household domain fields. Previously it silently omitted values such as room count from new snapshots. The fix was verified with a fresh normally published household and change request. Existing historical rows were not rewritten.']
links=''.join('<li><a href="'+html.escape(name)+'">'+html.escape(name)+'</a></li>' for name in sorted(ui))
page=f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Published household change requests</title><style>body{{font:16px/1.6 system-ui;background:#f1f5f0;color:#173e34;margin:0}}main{{max-width:1050px;margin:24px auto;padding:28px;background:white;border:1px solid #d2dfd3;border-radius:16px}}h1,h2,a{{color:#155e50}}li{{margin:10px 0}}img{{width:100%;max-width:390px;border:1px solid #d2dfd3;border-radius:12px}}</style><main><h1>Published household change requests: passed</h1><p>13 November 2026 · Four isolated fictional households were published through the normal two-approval process before testing their change requests. No existing household was edited.</p><h2>Workflow and layout checks</h2><ul>'''+''.join('<li>'+html.escape(c)+'</li>' for c in checks)+f'''</ul><p>Passed {sum(len(r['checks']) for r in ui.values())} UI view/action checks with officer and both approver accounts.</p><h2>Issues fixed and deployed</h2><ul>'''+''.join('<li>'+html.escape(f)+'</li>' for f in fixes)+f'''</ul><h2>Cleanup and preservation</h2><p>Removed only the four UUID-tracked fictional households, their members, change requests and test approval attempts after archiving evidence. Reconciliation passed: {preserved['native_rows_verified']} native rows and {preserved['awe_rows_verified']} original approval-history rows unchanged. Master totals returned to {preserved['households']} households and {preserved['individuals']} individuals.</p><p><a href="returned.json">Return and approval evidence</a> · <a href="rejected.json">Level-1 rejection</a> · <a href="rejected-level2.json">Level-2 rejection</a> · <a href="history.json">History-value regression</a> · <a href="fixture-cleanup.json">Cleanup evidence</a></p><h2>Browser evidence</h2><ul>{links}</ul><img src="editor-preview-390.png" alt="Readable household correction editor on mobile"></main></html>'''
(out/'verification.html').write_text(page,encoding='utf-8');print('Built published household change-request verification report')
